For other nix users, here's a similar solve to @MiguVT's - just using overrideAttrs instead of redefining the whole derivation: 

<details>
<summary>Overlays for both bun 1.4.0 and opencode 2.0.15</summary>

```nix
  overlays = [
    # Each overlay is a function that takes two arguments: final and prev
    (final: prev: {
      # Override an existing package
      bun = let
        sources = {
          "aarch64-darwin" = prev.fetchurl {
            url = "https://github.com/oven-sh/bun/releases/download/bun-v1.4.0/bun-darwin-aarch64.zip";
            hash = "sha256-xmnpf2Fk4cluBwF0jbmN+ndJKQjL2DlMdVcTSnNd44E=";
          };
          "aarch64-linux" = prev.fetchurl {
            url = "https://github.com/oven-sh/bun/releases/download/bun-v1.4.0/bun-linux-aarch64.zip";
            hash = "sha256-SxozLuhhmD65O8/m93D/+U4+MbLDiL2uo8jtNeWO7Q4=";
          };
          "x86_64-linux" = prev.fetchurl {
            url = "https://github.com/oven-sh/bun/releases/download/bun-v1.4.0/bun-linux-x64-baseline.zip";
            hash = "sha256-GE+0WV8NQBohfPfHjBvEMLqDMU2reouUgFurv3+nCX8=";
          };
        };
      in
        prev.bun.overrideAttrs {
          version = "1.4.0";
          src = sources.${prev.stdenvNoCC.hostPlatform.system};
          passthru.sources = sources;
        };

      opencode = prev.opencode.overrideAttrs (finalAttrs: prevAttrs: {
        version = "2.0.15";
        src = pkgs.fetchFromGitHub {
          owner = "anomalyco";
          repo = "opencode";
          tag = "v${finalAttrs.version}";
          hash = "sha256-G4qRDwJ6i5SpsiHoej31HRPLOHpkLc66B+UmdzOY1+o=";
        };
        passthru.node_modules = prevAttrs.passthru.node_modules.overrideAttrs {
          outputHash = "sha256-d3/tMh6B+econOcX+5orEsy3aVXmfnptaR76UAyNn48=";
        };
      });
    })
  ];

```


</details>

