```ts
/**
* OpenCode TUI plugin: fixes markdown streaming truncation (Issue #48155)
*
* Root cause (v1.18.29): in @opentui/core the list-child and blockquote
* CodeRenderables are created/updated without a synchronous styled text, so they
* rely on async Tree-Sitter highlights. The TUI renders assistant markdown in
* `internalBlockMode:"top-level"` and freezes rendered rows into the terminal
* scrollback via a ScrollbackSurface commit. If a block is drawn/committed while
* a list/blockquote child holds only an unstyled prefix, the truncation is
* written to the terminal once and is permanent (resize does not rewrite
* scrollback).
*
* Fix (two layers, no rebuild):
*   1. Renderable side: wrap the create AND update paths for list children and
*      blockquotes so the child always receives a full synchronous styled text,
*      even when the renderable is not streaming (finalization), by briefly
*      forcing `_streaming` while calling createInitialStyledText.
*   2. Commit/paint side: wrap `MarkdownRenderable.renderSelf` so the full styled
*      text is restored into every child's text buffer immediately before the
*      render that produces the pixels the scrollback surface snapshots. This is
*      the tightest anchor an external plugin can reach: the ScrollbackSurface
*      and the transcript renderer are module-internal (not exported), but every
*      frame and every scrollback commit is drawn through this renderSelf.
*
* No `import "@opentui/core"`: external plugin files cannot resolve the runtime's
* bundled copy (ERR_MODULE_NOT_FOUND). Instead the plugin walks the compiled
* chunk graph ($bunfs) from Bun.main, imports the chunk exporting the runtime
* MarkdownRenderable, and patches its prototype — guaranteeing identity with the
* classes the TUI actually uses. The resolved chunk path is cached in kv and
* re-discovered automatically after every binary upgrade.
*/


const KV_KEY = "fix-markdown-stream.chunk"
const SERVICE = "fix-markdown-stream"


function log(api: any, msg: string) {
  try {
    api?.client?.app?.log({ body: { service: SERVICE, level: "info", message: msg } })
  } catch {}
  try {
    console.error(`[${SERVICE}] ${msg}`)
  } catch {}
}


function isMarkdownRenderableClass(C: any): boolean {
  const p = C?.prototype
  return (
    typeof C === "function" &&
    typeof p?.applyListChildRenderable === "function" &&
    typeof p?.applyMarkdownCodeRenderable === "function"
  )
}


function patchable(C: any): boolean {
  const p = C?.prototype
  return (
    !!p &&
    typeof p.applyMarkdownCodeRenderable === "function" &&
    typeof p.normalizeScrollbackMarkdownBlockRaw === "function" &&
    typeof p.createInitialStyledText === "function"
  )
}


function findMarkdownClassIn(mod: any): any {
  try {
    for (const k of Object.keys(mod ?? {})) {
      const E = mod[k]
      if (isMarkdownRenderableClass(E) && patchable(E)) return E
    }
  } catch {}
  return undefined
}


const GRAPH = /(\/\$bunfs\/root\/(?:chunk-[a-z0-9]+|src\/[A-Za-z0-9._/-]+)\.js)/g


// Build the full synchronous styled text for an inline token, even when the
// markdown renderable is not currently streaming (finalization).
function buildStyledText(self: any, token: any): any {
  if (!token) return undefined
  try {
    const saved = self._streaming
    if (!saved) self._streaming = true
    try {
      return self.createInitialStyledText(token)
    } finally {
      self._streaming = saved
    }
  } catch {
    return undefined
  }
}


function isInlineToken(token: any): boolean {
  return !!token && (token.type === "text" || token.type === "paragraph")
}


